// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address alloSettings = address(0x5678);
        address roundImpl = address(0x9abc);

        c.initialize();
        c.updateAlloSettings(alloSettings);
        c.updateRoundImplementation(payable(roundImpl));

        vm.prank(address(this));
        c.programOperators(nonOwner);

        bool ok;
        vm.prank(nonOwner);
        try c.updateRoundImplementation(payable(address(0xdead))) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}
